// Copy the IDL + TS types generated by `anchor build` into packages/sdk/src/idl/ (pnpm sdk:sync-idl).
// The SDK encodes instructions from its own layouts; the IDL ships for explorers, Codama and other clients.
import { copyFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const outDir = resolve(root, "packages/sdk/src/idl");
mkdirSync(outDir, { recursive: true });
for (const [from, to] of [
  ["target/idl/leash.json", "leash.json"],
  ["target/types/leash.ts", "leash.ts"],
]) {
  const src = resolve(root, from);
  if (!existsSync(src)) {
    console.error(`missing ${from}: run \`anchor build\` first`);
    process.exit(1);
  }
  copyFileSync(src, resolve(outDir, to));
  console.log(`${from} -> packages/sdk/src/idl/${to}`);
}
